def safe_pop(stack):
    if not stack:
        return False, None
    return True, stack.pop()

for stack in [[], [None], [1, 2]]:
    print(safe_pop(stack), stack)

def parentheses_ok(text):
    stack = []
    for character in text:
        if character == "(":
            stack.append(character)
        elif character == ")":
            if not stack:
                return False
            stack.pop()
    return not stack

for text in ["", "(())", "())(", "a(b)c"]:
    print(parentheses_ok(text))

def edit_history(actions):
    text = ""
    history = []
    for action in actions:
        if action is None:
            if history:
                text = history.pop()
        else:
            history.append(text)
            text = action
    return text, history

print(edit_history([]))
print(edit_history(["A", "AB", None]))
print(edit_history([None, "A", None, None]))
